import heapq

def match(orders):
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}  # id -> {'side', 'price', 'qty', 'seq'}
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty
        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            top_id = top[2]

            if top_id not in book:
                heapq.heappop(opp_heap)
                continue

            resting = book[top_id]
            resting_price = resting['price']

            if typ == 'market':
                ok = True
            else:
                if side == 'buy':
                    ok = resting_price <= price
                else:
                    ok = resting_price >= price

            if not ok:
                break

            heapq.heappop(opp_heap)

            trade_qty = min(remaining, resting['qty'])
            resting['qty'] -= trade_qty
            remaining -= trade_qty

            if side == 'buy':
                trades.append([oid, top_id, resting_price, trade_qty])
            else:
                trades.append([top_id, oid, resting_price, trade_qty])

            if resting['qty'] == 0:
                if top_id in book:
                    del book[top_id]
            else:
                heapq.heappush(opp_heap, top)

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

